include '../../koneksi.php';
include '../../koneksi3.php';
if (empty($_SESSION['UserName'])) { $_SESSION['error']='Silakan login terlebih dahulu!'; header('Location: /gg_app/login.php'); exit; }
include '../../includes/header.php'; include '../../includes/sidebar.php';
date_default_timezone_set('Asia/Jakarta');
$themeColor=$_SESSION['Theme']??'primary'; $groupId=$_SESSION['GroupId']??0; $menuId=34;
$permStmt=sqlsrv_query($conn,'SELECT TOP 1 CanView, CanEdit FROM dbo.SMGroupTrustee WHERE GroupId=? AND MenuId=?',[$groupId,$menuId]);
$permissions=$permStmt ? sqlsrv_fetch_array($permStmt,SQLSRV_FETCH_ASSOC) : [];
$orgParam=isset($_GET['org'])?(string)$_GET['org']:'all';
$orgId=$orgParam==='all'||$orgParam===''?null:(int)$orgParam;
$status=($_GET['status']??'O')==='V'?'V':'O';
$orgs=$conn3->query('SELECT prorgid, prorgname FROM prprorg ORDER BY prorgname')->fetchAll(PDO::FETCH_ASSOC);
$q='SELECT h.ppnmbr,h.ppdate,h.createdby,h.ppdesc,h.fgstatus,h.approveby,h.approvedate,o.prorgname,h.ppprorgid,o.prorgid FROM prpphd h INNER JOIN prprorg o ON h.ppprorgid=o.prorgid WHERE h.fgstatus=:status'.($orgId!==null?' AND h.ppprorgid=:org':'').' ORDER BY h.ppdate DESC,h.ppnmbr DESC';
$s=$conn3->prepare($q); $params=[':status'=>$status]; if($orgId!==null)$params[':org']=$orgId; $s->execute($params); $rows=$s->fetchAll(PDO::FETCH_ASSOC);
?>
<div class="wrapper"><div class="content-wrapper"><div class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-6"><h1 class="m-0">Purchase Request</h1></div><div class="col-sm-6"><ol class="breadcrumb float-sm-right"><li class="breadcrumb-item"><a href="/gg_app/index.php">Beranda</a></li><li class="breadcrumb-item active">Purchase Request</li></ol></div></div></div></div><div class="content"><div class="container-fluid"><div class="row"><div class="col-12"><div class="card"><div class="card-header bg-<?= htmlspecialchars($themeColor) ?> text-white"><h3 class="card-title"><i class="fas fa-list mr-1"></i> Daftar Purchase Request</h3></div><div class="card-body">
<form method="get" class="form-inline mb-3"><div class="form-group mr-2"><label class="mr-2" for="org">PR Organization:</label><select class="form-control form-control-sm" id="org" name="org" onchange="this.form.submit()"><option value="all" <?= $orgId===null?'selected':'' ?>>All</option><?php foreach($orgs as $o): ?><option value="<?= (int)$o['prorgid'] ?>" <?= $orgId===(int)$o['prorgid']?'selected':'' ?>><?= htmlspecialchars($o['prorgname']) ?></option><?php endforeach ?></select></div><div class="form-group mr-2"><label class="mr-2" for="status">Status:</label><select class="form-control form-control-sm" id="status" name="status" onchange="this.form.submit()"><option value="O" <?= $status==='O'?'selected':'' ?>>Open (Belum Approve)</option><option value="V" <?= $status==='V'?'selected':'' ?>>Approve</option></select></div><?php if(!empty($permissions['CanEdit'])): ?><button id="bulk-action" type="button" class="btn btn-<?= $status==='O'?'success':'warning' ?> btn-sm mr-2"><i class="fas fa-<?= $status==='O'?'check-circle':'times-circle' ?>"></i> <?= $status==='O'?'Approve':'Unapprove' ?> Selected</button><?php endif ?><button type="submit" class="btn btn-info btn-sm"><i class="fas fa-sync-alt"></i> Refresh</button></form>
<form id="bulk-form"><input type="hidden" name="action" value="<?= $status==='O'?'approve':'unapprove' ?>">
<div class="table-responsive"><table id="prTable" class="table table-hover table-sm"><thead class="thead-light"><tr><?php if(!empty($permissions['CanEdit'])): ?><th><input type="checkbox" id="select-all"></th><?php endif ?><th>NO</th><th>No PR</th><th>Date</th><th>Requested by Name</th><th>Description</th><th>Status</th><th>Approve by</th><th>Approved date</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr><?php if(!empty($permissions['CanEdit'])): ?><td><input class="pr-check" type="checkbox" name="ppnmbrs[]" value="<?= htmlspecialchars($r['ppnmbr'],ENT_QUOTES) ?>"></td><?php endif ?><td><?= $i+1 ?></td><td><?= htmlspecialchars($r['ppnmbr']) ?></td><td><?= $r['ppdate']?date('d/m/Y',strtotime($r['ppdate'])):'-' ?></td><td><?= htmlspecialchars($r['createdby']??'') ?></td><td><?= htmlspecialchars($r['ppdesc']??'') ?></td><td><span class="badge badge-<?= $r['fgstatus']==='O'?'warning':'success' ?>"><?= $r['fgstatus']==='O'?'Open':'Approve' ?></span></td><td><?= htmlspecialchars($r['approveby']??'-') ?></td><td><?= !empty($r['approvedate'])?date('d/m/Y H:i',strtotime($r['approvedate'])):'-' ?></td><td><a class="btn btn-info btn-xs" title="Lihat PR" href="view_order.php?ppnmbr=<?= rawurlencode($r['ppnmbr']) ?>&org=<?= $orgId??'all' ?>&status=<?= $status ?>"><i class="fas fa-eye"></i></a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="10" class="text-center">Tidak ada data yang tersedia</td></tr><?php endif ?></tbody></table></div></form>
</div></div></div></div></div></div></div><?php include '../../includes/footer.php'; ?>
<link rel="stylesheet" href="/gg_app/plugins/AdminLTE-3.2.0/plugins/datatables-bs4/css/dataTables.bootstrap4.min.css"><script src="/gg_app/plugins/AdminLTE-3.2.0/plugins/datatables/jquery.dataTables.min.js"></script><script src="/gg_app/plugins/AdminLTE-3.2.0/plugins/datatables-bs4/js/dataTables.bootstrap4.min.js"></script><script src="/gg_app/plugins/AdminLTE-3.2.0/plugins/sweetalert2/sweetalert2.all.min.js"></script><script>$(function(){if($('#prTable').length)$('#prTable').DataTable({responsive:true});$('#select-all').on('change',function(){$('.pr-check').prop('checked',this.checked)});$('#bulk-action').on('click',function(){const ids=$('.pr-check:checked').map(function(){return this.value}).get();if(!ids.length){Swal.fire('Peringatan','Pilih minimal satu PR.','warning');return}Swal.fire({title:'Proses '+ids.length+' PR?',icon:'question',showCancelButton:true,confirmButtonText:'Ya, lanjutkan'}).then(function(result){if(!result.isConfirmed)return;$.post('proses_approve.php',{action:'<?= $status==='O'?'approve':'unapprove' ?>',ppnmbrs:ids},function(res){if(res.status==='success')location.reload();else Swal.fire('Gagal',res.message,'error')},'json').fail(function(x){Swal.fire('Gagal',x.responseJSON?.message||'Permintaan gagal diproses.','error')})})})});</script>
